// Overworld: tile rendering, grid movement, warps, NPCs, encounters, scripts.
window.Overworld = (() => {
  const TILE = 16, VIEW_W = 240, VIEW_H = 160;
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const rnd = (n) => (Math.random() * n) | 0;

  const P = { map: 'player-house', x: 4, y: 5, dir: 'down', step: 0, stepFrame: 0, moving: false };
  let busyScript = false;
  let waterFrame = 0;

  const player = P;

  function setPos(map, x, y, dir) {
    P.map = map; P.x = x; P.y = y; P.dir = dir ?? P.dir;
    P.moving = false; P.step = 0;
    const m = Maps.get(map);
    Audio2.music(m.music ?? 'overworld');
  }

  function mapNpcs(m) {
    return (m.npcs ?? []).filter(n => !(n.hideFlag && Game.save.flags[n.hideFlag]));
  }

  function solidAt(m, x, y) {
    const c = Maps.cell(m, x, y);
    if (!c) return true;
    if (c.solid) return true;
    for (const n of mapNpcs(m)) if (n.x === x && n.y === y) return true;
    return false;
  }

  // ---- Movement & world simulation ----------------------------------------
  function update() {
    waterFrame++;
    if (busyScript || UI.busy() || Battle.active()) return;

    if (Input.press('menu')) { startMenu(); return; }
    if (Input.press('a')) { interact(); return; }

    const m = Maps.get(P.map);
    if (P.moving) {
      P.step += 2.2;
      if (P.step >= TILE) {
        P.step = 0; P.moving = false;
        onArrive(m);
      }
      return;
    }
    const dir = Input.dirHeld();
    if (!dir) return;
    if (dir !== P.dir) { P.dir = dir; }
    const [dx, dy] = delta(dir);
    const nx = P.x + dx, ny = P.y + dy;

    // map connections at edges
    const conn = m.connections ?? {};
    if (ny < 0 && conn.north) { transition(conn.north.map, P.x + conn.north.offset, Maps.get(conn.north.map).h - 1, 'up'); return; }
    if (ny >= m.h && conn.south) { transition(conn.south.map, P.x + conn.south.offset, 0, 'down'); return; }
    if (nx < 0 && conn.west) { transition(conn.west.map, Maps.get(conn.west.map).w - 1, P.y + conn.west.offset, 'left'); return; }
    if (nx >= m.w && conn.east) { transition(conn.east.map, 0, P.y + conn.east.offset, 'right'); return; }

    if (solidAt(m, nx, ny)) return;
    P.x = nx; P.y = ny; P.moving = true; P.step = 0; P.stepFrame++;
  }

  function delta(dir) {
    return dir === 'up' ? [0, -1] : dir === 'down' ? [0, 1] : dir === 'left' ? [-1, 0] : [1, 0];
  }

  async function transition(map, x, y, dir) {
    busyScript = true;
    await fade(true);
    setPos(map, x, y, dir);
    await fade(false);
    busyScript = false;
  }

  let fadeAlpha = 0;
  async function fade(out) {
    for (let i = 0; i <= 8; i++) { fadeAlpha = out ? i / 8 : 1 - i / 8; await wait(28); }
  }

  function onArrive(m) {
    // warps
    for (const w of m.warps ?? []) {
      if (w.x === P.x && w.y === P.y) {
        if (w.locked) {
          script(async () => {
            await UI.message(w.locked);
            const [dx, dy] = delta(P.dir);
            P.x -= dx; P.y -= dy; // step back off the door
          });
          return;
        }
        transition(w.map, w.tx, w.ty, w.dir);
        return;
      }
    }
    // trainer line of sight
    for (const n of mapNpcs(m)) {
      if (!n.trainer || Game.save.defeated[n.id] || !n.sight) continue;
      const seen =
        (n.x === P.x && ((n.dir === 'down' && P.y > n.y && P.y - n.y <= n.sight) || (n.dir === 'up' && P.y < n.y && n.y - P.y <= n.sight))) ||
        (n.y === P.y && ((n.dir === 'right' && P.x > n.x && P.x - n.x <= n.sight) || (n.dir === 'left' && P.x < n.x && n.x - P.x <= n.sight)));
      if (seen) { trainerBattle(n); return; }
    }
    // wild encounters
    const cell = Maps.cell(m, P.x, P.y);
    if (cell?.grass && m.encounters && Math.random() < m.encounters.rate) {
      const [id, lo, hi] = rollEncounter(m.encounters.grass);
      wildBattle(id, lo + rnd(hi - lo + 1));
    }
  }

  function rollEncounter(table) {
    const total = table.reduce((s, e) => s + e[1], 0);
    let r = Math.random() * total;
    for (const [id, w, lo, hi] of table) {
      r -= w;
      if (r <= 0) return [id, lo, hi];
    }
    const last = table[table.length - 1];
    return [last[0], last[2], last[3]];
  }

  function script(fn) {
    busyScript = true;
    Promise.resolve(fn()).finally(() => { busyScript = false; });
  }

  // ---- Battles --------------------------------------------------------------
  function wildBattle(id, level) {
    script(async () => {
      await fade(true); fadeAlpha = 0;
      const result = await Battle.start(Game.save, { wild: Pkmn.make(id, level) });
      Audio2.music(Maps.get(P.map).music ?? 'overworld');
      if (result === 'lose') await blackout();
      await Game.runEvolutions();
    });
  }

  function trainerBattle(n) {
    script(async () => {
      await UI.message(n.trainer.intro ?? `${n.trainer.name} wants\nto battle!`);
      await fade(true); fadeAlpha = 0;
      const party = n.trainer.party.map(([id, lv]) => Pkmn.make(id, lv));
      const result = await Battle.start(Game.save, {
        trainer: { ...n.trainer, party },
      });
      Audio2.music(Maps.get(P.map).music ?? 'overworld');
      if (result === 'lose') { await blackout(); return; }
      Game.save.defeated[n.id] = true;
      if (n.script === 'brock' && !Game.save.flags.badge) {
        Game.save.flags.badge = true;
        Audio2.levelUp();
        await UI.message('You received the\nBOULDERBADGE from BROCK!');
        await UI.message("BROCK: That BADGE proves you've\nbeaten the PEWTER GYM.", {});
        await UI.message('Your journey is only\nbeginning. CERULEAN CITY\nawaits… someday!');
        await UI.message('CONGRATULATIONS!\nYou beat the demo story!\nCan you catch all 151?');
      }
      await Game.runEvolutions();
    });
  }

  async function blackout() {
    Game.save.money = Math.floor(Game.save.money / 2);
    await UI.message('You have no usable\nPOKéMON!');
    await UI.message('You blacked out!');
    await fade(true);
    for (const mon of Game.save.party) { mon.hp = mon.stats.hp; mon.status = null; }
    const r = Game.save.respawn;
    setPos(r.map, r.x, r.y, 'down');
    await fade(false);
  }

  // ---- Interactions ---------------------------------------------------------
  function interact() {
    const m = Maps.get(P.map);
    const [dx, dy] = delta(P.dir);
    const tx = P.x + dx, ty = P.y + dy;

    // NPC?
    for (const n of mapNpcs(m)) {
      if (n.x === tx && n.y === ty) {
        n.facing = { up: 'down', down: 'up', left: 'right', right: 'left' }[P.dir];
        runNpc(n);
        return;
      }
    }
    // sign?
    const sign = m.signs?.[tx + ',' + ty];
    if (sign) { script(() => UI.message(sign)); return; }
    // starter balls in lab
    if (m.starters && !Game.save.flags.starter) {
      const st = m.starters.find(s => s.x === tx && s.y === ty);
      if (st) { script(() => pickStarter(st.mon)); return; }
    }
    // PC
    if (m.pcAt && m.pcAt.x === tx && m.pcAt.y === ty) { script(() => pcBox()); return; }
    // water: fishing
    const cell = Maps.cell(m, tx, ty);
    if (cell?.water) {
      script(async () => {
        if (!Game.save.bag['old-rod']) { await UI.message("The water is calm…\nIf only you had a ROD."); return; }
        if (!(await UI.confirm('Use the OLD ROD?'))) return;
        await UI.message('You cast the line…');
        await wait(900);
        if (Math.random() < 0.7) {
          await UI.message('Oh! A bite!');
          const [id, lo, hi] = rollEncounter(Maps.ENC.fish);
          await fade(true); fadeAlpha = 0;
          const result = await Battle.start(Game.save, { wild: Pkmn.make(id, lo + rnd(hi - lo + 1)) });
          Audio2.music(m.music ?? 'overworld');
          if (result === 'lose') await blackout();
          await Game.runEvolutions();
        } else {
          await UI.message('Not even a nibble…');
        }
      });
      return;
    }
  }

  function runNpc(n) {
    script(async () => {
      switch (n.script) {
        case 'mom':
          await UI.message('MOM: Oh good, you’re home!');
          if (Game.save.party.length) {
            for (const mon of Game.save.party) { mon.hp = mon.stats.hp; mon.status = null; for (const mv of mon.moves) mv.pp = mv.maxPp; }
            Audio2.heal();
            await UI.message('MOM: Your POKéMON look\ntired. There… all rested!');
          }
          await UI.message('MOM: PROF. OAK next door\nwas looking for you!');
          return;
        case 'nurse': {
          await UI.message('NURSE: Welcome to our\nPOKéMON CENTER!');
          if (Game.save.party.length) {
            Audio2.heal();
            await wait(600);
            for (const mon of Game.save.party) { mon.hp = mon.stats.hp; mon.status = null; for (const mv of mon.moves) mv.pp = mv.maxPp; }
            await UI.message('Your POKéMON are\nfully healed!');
          }
          Game.save.respawn = { map: P.map, x: P.x, y: P.y };
          await UI.message('We hope to see you again!');
          return;
        }
        case 'shop':
          await UI.shop(n.shop, Game.save);
          return;
        case 'rod-boy':
          if (!Game.save.flags.rod) {
            await UI.message("I love fishing! But I got\na new SUPER ROD, so…");
            Game.save.flags.rod = true;
            Game.save.bag['old-rod'] = 1;
            Audio2.levelUp();
            await UI.message('You received an OLD ROD!');
            await UI.message('Face any water and press A\nto fish. Try the pond in\nPALLET TOWN!');
          } else {
            await UI.message('Catch anything good yet?\nI hear LAPRAS lurk in\ndeep water…');
          }
          return;
        case 'oak':
          if (!Game.save.flags.starter) {
            await UI.message('OAK: Ah, hello!\nI’m PROFESSOR OAK.');
            await UI.message('OAK: On the table are three\nPOKé BALLS. Inside each is\na rare POKéMON.');
            await UI.message('OAK: Go on, pick one!\nIt will be your partner.');
          } else if (!Game.save.flags.badge) {
            await UI.message('OAK: How is your POKéDEX\ncoming along?');
            const caught = Object.keys(Game.save.caught).length;
            await UI.message(`OAK: You've caught ${caught}\nkind(s) so far. Keep it up!`);
          } else {
            await UI.message('OAK: A BADGE already?!\nYou really are something.');
          }
          return;
        case 'rival-lab':
          await UI.message('BLUE: Gramps said to wait\nhere. So I’m waiting.');
          return;
        case 'brock':
          if (Game.save.defeated['brock']) {
            await UI.message('BROCK: Go on to CERULEAN…\nMISTY will test you next!\n(…in the full game!)');
            return;
          }
          await trainerNpcBattle(n);
          return;
        default:
          if (n.trainer && !Game.save.defeated[n.id]) { await trainerNpcBattle(n); return; }
          for (const line of n.lines ?? ['…']) await UI.message(line);
      }
    });
  }

  async function trainerNpcBattle(n) {
    await UI.message(n.trainer.intro ?? `${n.trainer.name} wants\nto battle!`);
    await fade(true); fadeAlpha = 0;
    const party = n.trainer.party.map(([id, lv]) => Pkmn.make(id, lv));
    const result = await Battle.start(Game.save, { trainer: { ...n.trainer, party } });
    Audio2.music(Maps.get(P.map).music ?? 'overworld');
    if (result === 'lose') { await blackout(); return; }
    Game.save.defeated[n.id] = true;
    if (n.script === 'brock') {
      Game.save.flags.badge = true;
      Audio2.levelUp();
      await UI.message('You received the\nBOULDERBADGE from BROCK!');
      await UI.message('CONGRATULATIONS!\nYou beat the demo story!\nCan you catch all 151?');
    }
    await Game.runEvolutions();
  }

  async function pickStarter(id) {
    const sp = POKEDEX[id];
    const name = sp.displayName.toUpperCase();
    if (!(await UI.confirm(`Choose ${name},\nthe ${sp.types[0].toUpperCase()} POKéMON?`))) return;
    const mon = Pkmn.make(id, 5);
    Game.save.party.push(mon);
    Game.save.caught[id] = true; Game.save.seen[id] = true;
    Game.save.flags.starter = id;
    Game.save.bag['poke-ball'] = (Game.save.bag['poke-ball'] ?? 0) + 5;
    Game.save.bag['potion'] = (Game.save.bag['potion'] ?? 0) + 1;
    Audio2.catchSuccess();
    await UI.message(`You received ${name}!`);
    await UI.message('OAK: A fine choice!\nTake these POKé BALLS and\na POTION as well.');
    await UI.message('BLUE: Then I’ll take this\none! Heh, it’s stronger\nthan yours anyway!');
    await UI.message('BLUE: Hold on! Let’s check\nout our POKéMON!\nCome on, I’ll take you on!');
    // Rival picks the type-advantaged starter.
    const rivalPick = { 1: 4, 4: 7, 7: 1 }[id];
    const result = await Battle.start(Game.save, {
      trainer: {
        name: 'RIVAL BLUE', party: [Pkmn.make(rivalPick, 5)], prize: 80,
        defeat: 'BLUE: WHAT?! Unbelievable!\nI picked the wrong POKéMON!',
      },
    });
    Audio2.music('overworld');
    if (result === 'lose') {
      await UI.message('BLUE: Yeah! Am I great\nor what!');
      for (const m2 of Game.save.party) { m2.hp = m2.stats.hp; m2.status = null; }
    }
    Game.save.flags.rivalGone = true;
    await UI.message('BLUE: Smell ya later!');
    await UI.message('OAK: Raise your POKéMON in\nthe tall grass up north.\nGood luck on your journey!');
    await Game.runEvolutions();
  }

  async function pcBox() {
    Audio2.select();
    await UI.message('You booted up the PC.');
    while (true) {
      const pick = await UI.menu(['WITHDRAW', 'DEPOSIT', 'LOG OFF'], { x: 140, y: 30 });
      if (pick < 0 || pick === 2) break;
      if (pick === 0) {
        if (!Game.save.box.length) { await UI.message('The BOX is empty.'); continue; }
        if (Game.save.party.length >= 6) { await UI.message('Your party is full!'); continue; }
        const idx = await boxPick();
        if (idx < 0) continue;
        const mon = Game.save.box.splice(idx, 1)[0];
        Game.save.party.push(mon);
        await UI.message(`${Pkmn.dname(mon)} joined\nyour party!`);
