        if (pick < 0 || pick === 5) return;
        if (pick === 0) await UI.pokedex(Game.save);
        if (pick === 1) {
          if (!Game.save.party.length) { await UI.message('You have no POKéMON!'); continue; }
          const idx = await UI.party(Game.save.party, 'select', 'Choose a POKéMON.');
          if (idx < 0) continue;
          const act = await UI.menu(['SUMMARY', 'SWITCH', 'CANCEL'], { x: 150, y: 60 });
          if (act === 0) await summary(Game.save.party[idx]);
          if (act === 1) {
            const j = await UI.party(Game.save.party, 'select', 'Switch with which one?');
            if (j >= 0 && j !== idx) {
              const t = Game.save.party[idx];
              Game.save.party[idx] = Game.save.party[j];
              Game.save.party[j] = t;
              Audio2.select();
            }
          }
        }
        if (pick === 2) await overworldBag();
        if (pick === 3) await UI.message(`PLAYER: RED\nMONEY: $${Game.save.money}\nBADGES: ${Game.save.flags.badge ? 1 : 0}\nPLAY AREA: ${Maps.get(P.map).name}`);
        if (pick === 4) { Game.persist(); Audio2.heal(); await UI.message('Your progress has\nbeen saved!'); }
      }
    });
  }

  async function summary(mon) {
    const sp = Pkmn.species(mon);
    await UI.message(
      `${Pkmn.dname(mon)}  LV${mon.level}\n` +
      `${sp.types.map(t => t.toUpperCase()).join('/')}  HP ${mon.hp}/${mon.stats.hp}\n` +
      `ATK ${mon.stats.atk} DEF ${mon.stats.def} SPE ${mon.stats.spe}\n` +
      `SP.A ${mon.stats.spa} SP.D ${mon.stats.spd}\n` +
      `EXP ${mon.exp}\n` +
      'MOVES: ' + mon.moves.map(m => MOVES[m.name].displayName.toUpperCase()).join(', ')
    );
  }

  async function overworldBag() {
    const itemId = await UI.bag(Game.save.bag);
    if (!itemId) return;
    const item = Pkmn.ITEMS[itemId];
    if (item.kind === 'ball') { await UI.message("Better save those for\nwild POKéMON!"); return; }
    if (item.kind === 'key') { await UI.message('Face some water and\npress A to fish!'); return; }
    if (item.kind === 'stone') {
      const idx = await UI.party(Game.save.party, 'select', 'Use on which POKéMON?');
      if (idx < 0) return;
      const mon = Game.save.party[idx];
      const to = Pkmn.stoneEvolution(mon, itemId);
      if (!to) { await UI.message("It won't have any effect."); return; }
      Game.save.bag[itemId]--;
      await Game.evolveScene(mon, to);
      return;
    }
    const idx = await UI.party(Game.save.party, 'select', 'Use on which POKéMON?');
    if (idx < 0) return;
    await Battle.useItemOnMon(Game.save, itemId, Game.save.party[idx]);
  }

  // ---- Rendering --------------------------------------------------------------
  function draw(ctx) {
    const m = Maps.get(P.map);
    const px = P.x * TILE + (P.moving ? -delta(P.dir)[0] * (TILE - P.step) : 0);
    const py = P.y * TILE + (P.moving ? -delta(P.dir)[1] * (TILE - P.step) : 0);
    let camX = Math.round(px - VIEW_W / 2 + TILE / 2);
    let camY = Math.round(py - VIEW_H / 2 + TILE / 2);
    camX = Math.max(0, Math.min(m.w * TILE - VIEW_W, camX));
    camY = Math.max(0, Math.min(m.h * TILE - VIEW_H, camY));
    if (m.w * TILE < VIEW_W) camX = (m.w * TILE - VIEW_W) / 2;
    if (m.h * TILE < VIEW_H) camY = (m.h * TILE - VIEW_H) / 2;

    ctx.fillStyle = '#101018'; ctx.fillRect(0, 0, VIEW_W, VIEW_H);
    const x0 = Math.max(0, camX / TILE | 0), y0 = Math.max(0, camY / TILE | 0);
    for (let y = y0; y <= Math.min(m.h - 1, y0 + 11); y++) {
      for (let x = x0; x <= Math.min(m.w - 1, x0 + 15); x++) {
        const c = Maps.cell(m, x, y);
        let t = c.tile;
        if (t === 'water' && (waterFrame / 40 | 0) % 2) t = 'water2';
        ctx.drawImage(Gfx.T[t], x * TILE - camX, y * TILE - camY);
      }
    }

    // entities sorted by y
    const ents = mapNpcs(m).map(n => ({ kind: 'npc', n, x: n.x * TILE, y: n.y * TILE }));
    ents.push({ kind: 'player', x: px, y: py });
    ents.sort((a, b) => a.y - b.y);
    for (const e of ents) {
      if (e.kind === 'npc') {
        const sheet = Gfx.SHEETS[e.n.sheet] ?? Gfx.SHEETS.boy;
        const dir = e.n.facing ?? e.n.dir;
        ctx.drawImage(sheet[dir][0], e.x - camX, e.y - camY - 2);
        if (e.n.trainer && !Game.save.defeated[e.n.id] && e.n.sight) {
          // subtle "!" hint above undefeated trainers
          if ((waterFrame / 50 | 0) % 2) Gfx.text(ctx, '!', e.x - camX + 6, e.y - camY - 10, '#e05048');
        }
      } else {
        const sheet = Gfx.SHEETS.hero;
        const frames = sheet[P.dir];
        const f = P.moving ? frames[1 + (P.stepFrame % (frames.length - 1) === 0 ? 0 : frames.length - 2)] ?? frames[1] : frames[0];
        const fi = P.moving ? frames[(P.stepFrame % 2) + 1 >= frames.length ? 1 : (P.stepFrame % 2) + 1] : frames[0];
        ctx.drawImage(fi, e.x - camX, e.y - camY - 2);
      }
    }

    if (fadeAlpha > 0) {
      ctx.fillStyle = `rgba(8,8,16,${fadeAlpha})`;
      ctx.fillRect(0, 0, VIEW_W, VIEW_H);
    }
  }

  return { update, draw, setPos, player: P, wildBattle, script };
})();
